const state={tab:'home',stack:[],scroll:{},approved:{},proposals:{},publishedMethods:{},methods:{},editingCustom:{},draftAmounts:{},receiptOpen:{},month:9,hidden:new Set(),groupHidden:{},filter:'all',frozen:{},autofill:{},single:{},notice:true,displayName:'Connor',invites:{},groupDraft:null,modal:null,carousel:{},paymentResult:null,paymentSequence:0,photoDraft:null};
let toastTimer;
const gById=id=>groups.find(g=>g.id===id)||groups[0];
// Only submitted allocations change the current share; draft editors never publish by navigation.
const chargePeople = c => c.people || gById(c.group).people || people.slice(0, c.members || gById(c.group).members);
const equalAllocation = (total,count) => {const cents=Math.round(total*100),base=Math.floor(cents/count);return Array.from({length:count},(_,i)=>(base+(i<cents%count?1:0))/100);};
const currentAllocation = c => state.proposals[c.id] || c.allocation || equalAllocation(c.total,chargePeople(c).length);
const currentApprovalCount = c => state.approved[c.id] ? 1+(state.proposals[c.id]?0:c.initialApprovals??1) : state.proposals[c.id]?0:c.initialApprovals??1;
const currentPersonalAllocation = c => currentAllocation(c)[0];
function splitView(c) {
  const publishedMethod = state.publishedMethods[c.id] || c.initialMethod || 'equal';
  const method = state.methods[c.id] || publishedMethod;
  const draft = method !== publishedMethod || (method === 'custom' && !!state.editingCustom[c.id]);
  const allocations = !draft ? currentAllocation(c) : method === 'custom'
    ? state.draftAmounts[c.id] || currentAllocation(c)
    : method === 'item' && c.id === 'juniper' ? [38.55,42.41,43.69,29.55] : equalAllocation(c.total,chargePeople(c).length);
  return {method, draft, allocations};
}

const groupPhotos={apartment:'assets/apartment.jpg',weekend:'assets/weekend.jpg',roadtrip:'assets/roadtrip.jpg'};
const groupPhoto=g=>g.photo||groupPhotos[g.id];
const stamp=(g,size='')=>`<span class="group-icon ${g.tone} ${size} ${groupPhoto(g)?'has-photo':''}">${groupPhoto(g)?`<img src="${esc(groupPhoto(g))}" alt="" loading="lazy" decoding="async">`:icon(g.icon)}</span>`;
const merchantLogoKeys={spotify:'spotify',wholefoods:'wholefoods',ikea:'ikea',bluebottle:'bluebottle',groceries:'traderjoes',shell:'shell',costco:'costco'};
const merchantKey=c=>merchantLogoKeys[c.id]||({'spotify':'spotify','whole foods':'wholefoods','ikea':'ikea','blue bottle':'bluebottle','trader joe’s':'traderjoes',"trader joe's":"traderjoes",'shell':'shell','costco':'costco'}[String(c.merchant||c.name).toLowerCase()]);
const merchantMark=(c,large=false)=>{const key=merchantKey(c);return `<span class="merchant-mark ${large?'large':''} ${key||'generic'}" aria-hidden="true">${key?`<img src="assets/logo-${key}.${key==='wholefoods'?'png':'svg'}" alt="">`:icon(c.icon||'shopping-bag')}</span>`;};
const button=(label,action,extra='',type='')=>`<button type="button" class="button ${type}" data-action="${action}" ${extra}>${label}</button>`;
const backbar=(title,right='')=>`<header class="backbar"><button class="icon-btn" data-action="back" aria-label="Go back">${icon('arrow-left')}</button><strong>${esc(title)}</strong>${right||'<span class="spacer"></span>'}</header>`;
const avatar=(p=people[0],large=false)=>`<span class="avatar ${p.tone} ${large?'large':''}">${p.initials}</span>`;
function toast(message){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),4200);}
function current(){return state.stack.at(-1)||{type:state.tab};}
function routeKey(){const r=current();return r.type+':'+(r.id||'');}
function saveScroll(){const s=$('.screen');if(s)state.scroll[routeKey()]=s.scrollTop;}
function push(type,id){saveScroll();state.stack.push({type,id});render(true);}
function back(){saveScroll();state.stack.pop();render(true);}
function nav(tab){saveScroll();state.stack=[];state.tab=tab;render();}
function navBar(){return `<nav class="bottom-nav" aria-label="Main navigation">${[['home','home','Home'],['groups','grid','Groups'],['spending','bar-chart-2','Spending']].map(([id,i,t])=>`<button class="nav-button ${state.tab===id?'active':''}" data-action="tab" data-tab="${id}" ${state.tab===id?'aria-current="page"':''}><span class="nav-icon">${icon(i)}</span>${t}</button>`).join('')}</nav>`;}
function pendingCard(c){const g=gById(c.group);return `<button class="pending-card" data-action="split" data-id="${c.id}" aria-label="Review ${esc(c.name)}, your share ${money(currentPersonalAllocation(c))}, ${esc(g.name)}${state.approved[c.id]?', approved and waiting for others':''}"><div><div class="pending-title">${merchantMark(c)}<span>${esc(c.name)}${state.approved[c.id]?' · Waiting':''}</span></div><div class="pending-amount">${money(currentPersonalAllocation(c))}</div></div><div class="group-stamp">${stamp(g)}<span>${esc(g.name)}</span></div></button>`;}
function groupActions(){return `<div class="actions-pair groups-actions">${button(icon('plus')+' Create a group','create')}${button('Invitations <span class="tiny-badge">'+invites.filter(i=>!state.invites[i.id]).length+'</span>','invitations','','secondary')}</div>`;}
function home(){return `<header class="topbar"><button class="icon-btn" data-action="profile" aria-label="Open your profile">${avatar()}</button><button class="icon-btn" data-action="notifications" aria-label="Open notifications">${icon('bell')}${state.notice?'<span class="notification-dot"></span>':''}</button></header><h1 class="greeting">Hey, ${esc(state.displayName)} ${'<span style="font-size:22px">✦</span>'}</h1><div class="eyebrow greeting-sub">Good evening</div><section class="hero" aria-label="October settled spending"><div class="hero-head"><span>Your spend this month</span><span>October 2026</span></div><div class="hero-amount">${money(spendingTotal(9)).split('.')[0]}<span class="cents">.${money(spendingTotal(9)).split('.')[1]}</span></div>${homeSparkline()}<div class="hero-foot"><span>OCT 1</span><span>OCT 17</span></div></section><div class="section-heading"><h2>Pending charges <span class="count">${pending.length}</span></h2></div><div class="pending-list">${pending.slice(0,3).map(pendingCard).join('')}</div>${pending.length>3?button('See rest '+icon('arrow-right'),'all-pending','aria-label="See all '+pending.length+' pending charges"','secondary full see-rest'):''}`;}
function allPending(){return `${backbar('')}<h1 class="page-title charges-title">Charges</h1><div class="pending-list">${pending.map(pendingCard).join('')}</div>`;}
function groupsPage(){return `<div class="topbar"><div><h1 class="page-title">Your groups</h1><p class="eyebrow">Better together, everyday.</p></div></div>${groupActions()}<div class="groups-grid">${groups.map(g=>`<button class="group-tile" data-action="group" data-id="${g.id}">${stamp(g)}<h2>${esc(g.name)}</h2><p>${g.members} members · ${g.forming?'Invites pending':money(g.balance)+' yours'}</p></button>`).join('')}</div>`;}
function cardVisual(g){return `<div class="bank-card ${state.frozen[g.id]?'frozen':''}" role="img" aria-label="${esc(g.name)} sample virtual card ending 4826${state.frozen[g.id]?', frozen':''}"><div class="bank-top"><span>chipin<span style="color:#7a9eff">.</span></span>${icon(state.frozen[g.id]?'lock':'credit-card')}</div><div class="bank-chip"></div><div class="bank-number">•••• &nbsp; •••• &nbsp; •••• &nbsp; 4826</div><div class="bank-bottom"><span>${esc(state.displayName.toUpperCase())} ZACHARIAS<br><span style="font-size:8px;display:block;margin-top:5px;color:#8397b7">${esc(g.name.toUpperCase())}</span></span><strong>VISA</strong></div></div>`;}
function groupSpendPanel(g){const total=spendingTotal(9,g.id);return `<div class="group-spend-panel"><div class="row"><span class="eyebrow">Your group spending</span><span class="eyebrow">October</span></div><strong>${money(total)}</strong><svg viewBox="0 0 310 100" preserveAspectRatio="none" role="img" aria-label="${esc(g.name)} settled spending through October 17: ${money(total)}"><polyline points="${cumulativePoints(g.id,310,96,Math.max(total,1))}" fill="none" stroke="#2459e8" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="row"><span class="eyebrow">Settled · Through Oct 17</span><button class="text-action" data-action="group-menu" data-menu="statistics" data-id="${g.id}">View details ${icon('arrow-right')}</button></div></div>`;}
function groupCarousel(g){const panel=state.carousel[g.id]||0;return `<div class="group-carousel" data-carousel="${g.id}" tabindex="0" role="region" aria-roledescription="carousel" aria-label="Group card and spending. Use left or right arrow to switch."><div class="carousel-track" style="transform:translateX(-${panel*50}%)"><div class="carousel-panel" ${panel===1?'inert':''}><button class="card-launch" data-action="wallet" data-id="${g.id}" aria-label="Open mock Apple Pay for ${esc(g.name)}">${cardVisual(g)}</button></div><div class="carousel-panel" ${panel===0?'inert':''}>${groupSpendPanel(g)}</div></div></div><div class="carousel-controls" aria-label="Choose card or spending">${['Card','Spending'].map((name,i)=>`<button data-action="carousel" data-id="${g.id}" data-panel="${i}" aria-pressed="${panel===i}"><span class="carousel-dot"></span>${name}</button>`).join('')}</div>`;}
function setCarousel(id,panel){state.carousel[id]=Number(panel);const carousel=document.querySelector('[data-carousel="'+id+'"]');if(!carousel)return;carousel.querySelector('.carousel-track').style.transform='translateX(-'+panel*50+'%)';carousel.querySelectorAll('.carousel-panel').forEach((el,i)=>el.inert=i!==Number(panel));document.querySelectorAll('[data-action="carousel"][data-id="'+id+'"]').forEach((el,i)=>el.setAttribute('aria-pressed',String(i===Number(panel))));}
function groupDetail(id){const g=gById(id);return `${backbar('Group overview',`<button class="icon-btn" data-action="group-menu" data-id="${id}" data-menu="settings" aria-label="Group settings">${icon('settings')}</button>`)}<div class="group-identity">${stamp(g,'overview-photo')}<h1>${esc(g.name)}</h1></div>${groupCarousel(g)}<div class="fund-metrics"><div><small>Group buying power</small><div class="big">${money(g.power)}</div></div><div><small>Your balance</small><strong>${money(g.balance)}</strong></div><div><small>Available after holds</small><strong>${money(g.available)}</strong></div></div>${g.forming?'<div class="callout">'+icon('info')+'<span>This group activates after all invitations are resolved and at least two people join. No contribution has been collected in this preview.</span></div>':''}<div class="list-menu">${[['funds','dollar-sign','Funds','Add or withdraw'],['card','credit-card','Card controls','Details and freeze card']].map(([m,i,t,detail])=>`<button class="menu-row" data-action="group-menu" data-id="${id}" data-menu="${m}">${icon(i)}<span class="menu-copy">${t}<small>${detail}</small></span>${icon('chevron-right')}</button>`).join('')}</div>`;}
const colors={apartment:'#2459e8',weekend:'#b57439',roadtrip:'#8a70bd'};
const monthCharges = month => month === 9 ? charges : [];
const spendingTotal = (month, groupId) => monthCharges(month).filter(c => !groupId || c.group === groupId).reduce((sum,c) => sum + Math.round(c.amount * 100), 0) / 100;

function cumulativePoints(groupId, width, height, maximum) {
  const series = monthCharges(9).filter(c => !groupId || c.group === groupId);
  return Array.from({length:17},(_,index) => {
    const day=index+1;
    const cents=series.filter(c => Number(c.date.split(' ')[1]) <= day).reduce((sum,c) => sum+Math.round(c.amount*100),0);
    return `${(index * width / 16).toFixed(2)},${(height - cents / 100 / maximum * (height-8)).toFixed(2)}`;
  }).join(' ');
}
function homeSparkline(){const points=cumulativePoints(null,320,75,spendingTotal(9));return `<svg class="hero-chart" viewBox="0 0 320 80" preserveAspectRatio="none" role="img" aria-label="Cumulative settled spending from October 1 through October 17: ${money(spendingTotal(9))}"><polygon points="0,80 ${points} 320,80" fill="#497cff" fill-opacity=".12"/><polyline points="${points}" fill="none" stroke="#6890ff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}

function spending(groupId){
  const selected=groupId||state.filter==='all'?null:state.filter;
  const activeGroups=groups.filter(g=>!g.forming&&(!groupId||g.id===groupId));
  const shown=activeGroups;
  const total=shown.reduce((sum,g)=>sum+spendingTotal(state.month,g.id),0);
  const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
  const visibleCharges=[...pending.filter(c=>c.month===state.month).map(c=>({...c,isPending:true})),...monthCharges(state.month)].filter(c=>(!groupId||c.group===groupId)&&(groupId||state.filter==='all'||c.group===state.filter));
  const hasData=monthCharges(state.month).length>0;
  return `${groupId?backbar('Group statistics'):'<h1 class="page-title">Spending</h1><p class="eyebrow">A clearer picture of your shared life.</p>'}<div class="month-selector"><button data-action="month" data-dir="-1" aria-label="Previous month" ${state.month===0?'disabled':''}>${icon('chevron-left')}</button><strong>${months[state.month]} 2026</strong><button data-action="month" data-dir="1" aria-label="Next month" ${state.month===11?'disabled':''}>${icon('chevron-right')}</button></div><section class="card-section" style="padding:21px 19px"><div class="eyebrow">${groupId?'Your spending · '+esc(gById(groupId).name):'Your total spending'}</div><div class="spending-total">${money(total)}</div><p class="spending-caption">${hasData?'Settled purchases · Through October 17':'No sample purchases this month'}</p>${hasData?`<div class="chart-wrap"><svg class="spending-chart" viewBox="0 0 310 178" preserveAspectRatio="none" role="img" aria-label="Cumulative settled spending through October 17. ${shown.map(g=>g.name+' '+money(spendingTotal(state.month,g.id))).join(', ')}">${[25,66,107,148].map(y=>`<line x1="0" y1="${y}" x2="310" y2="${y}" stroke="#e8ebf0" stroke-dasharray="3 5"/>`).join('')}${shown.map(g=>`<polyline points="${cumulativePoints(g.id,310,157,520)}" fill="none" stroke="${selected&&selected!==g.id?'#c4cad4':colors[g.id]||'#2459e8'}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="310" cy="${157-spendingTotal(state.month,g.id)/520*149}" r="3.5" fill="${selected&&selected!==g.id?'#c4cad4':colors[g.id]||'#2459e8'}" stroke="white" stroke-width="2"/>`).join('')}</svg><div class="chart-axis"><span>1 Oct</span><span>5</span><span>9</span><span>13</span><span>17</span></div></div>`:'<div class="empty"><p>There is no sample spending history for this month.</p></div>'}<div class="legend">${activeGroups.map(g=>`<button class="${selected===g.id?'selected':selected?'dimmed':''}" data-action="legend" data-id="${g.id}" aria-pressed="${!selected||selected===g.id}"><span class="legend-dot" style="background:${colors[g.id]||'#2459e8'}"></span>${esc(g.name)}</button>`).join('')}</div></section><div class="section-heading"><h2>All charges</h2>${!groupId?`<select class="filter-select" id="charge-filter" aria-label="Filter charges by group"><option value="all">All groups</option>${activeGroups.map(g=>`<option value="${g.id}" ${state.filter===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select>`:''}</div>${visibleCharges.length?visibleCharges.map(c=>`<button class="charge-row ${c.isPending?'is-pending':''}" data-action="${c.isPending?'split':'charge'}" data-id="${c.id}" aria-label="${esc(c.name)}, ${c.isPending?'pending, current share '+money(currentPersonalAllocation(c)):'settled, '+money(c.amount)}, ${esc(gById(c.group).name)}">${merchantMark(c,true)}<span class="charge-copy"><strong>${esc(c.name)}</strong><small>${esc(gById(c.group).name)} · ${c.date}</small></span><span class="charge-price">${money(c.isPending?currentPersonalAllocation(c):c.amount)}<small>${c.isPending?'Pending':'Settled'}</small></span></button>`).join(''):'<div class="empty"><p>No charges match this month and selection.</p></div>'}`;
}
function split(id){const c=pending.find(x=>x.id===id);const {method,draft,allocations}=splitView(c);const approved=state.approved[id];const proposed=!!state.proposals[id];const isJuniper=id==='juniper';const members=chargePeople(c);return `${backbar(c.name)}${approved||proposed?`<div class="split-state"><span class="pill ${approved?'pending':''}">${approved?'Waiting for the group':'Proposed split'}</span></div>`:''}<div class="split-summary"><h1>${draft?'Current share':'Your share'}</h1><div class="share" id="split-share">${money(currentPersonalAllocation(c))}</div><p class="split-summary-context">of ${money(c.total)} · ${esc(gById(c.group).name)}</p>${draft?`<p class="sticky-draft" id="sticky-draft-amount">Draft ${money(allocations[0])} · not sent</p>`:''}</div><div class="split-meta">${icon('users')} ${currentApprovalCount(c)} of ${members.length} approved</div>${approved?`<div class="status-banner">${icon('check-circle')}<span>Your share is approved. We’re waiting for the other members. This purchase remains pending.</span></div>`:''}<div class="segmented" role="group" aria-label="Split method">${[['item','By item'],['equal','Equally'],['custom','Custom']].map(([v,t])=>`<button class="${method===v?'active':''}" data-action="split-method" data-id="${id}" data-method="${v}" aria-pressed="${method===v}" ${approved?'disabled':''}>${t}</button>`).join('')}</div><section class="card-section"><div class="row"><h2 style="margin:0">The split</h2>${draft?'<span class="pill pending">Unsent draft</span>':'<span class="label-upper">YOUR GROUP</span>'}</div>${members.map((p,i)=>`<div class="person-row">${avatar(p)}<div class="person-info"><strong>${i===0?esc(state.displayName)+' (you)':esc(p.name)}</strong><small>${draft?'Draft allocation':i===0?(approved?'Approved':'Review your share'):proposed?'Waiting to review':i>0&&i<=(c.initialApprovals??1)?'Approved':'Waiting to review'}</small></div>${method==='custom'&&!approved&&draft?`<label><span class="sr-only" style="position:absolute;width:1px;height:1px;overflow:hidden">${p.name} share in dollars</span><input class="custom-input" aria-label="${p.name} share in dollars" inputmode="decimal" type="number" min="0" step=".01" value="${allocations[i].toFixed(2)}" data-person="${i}"></label>`:`<span class="amount">${money(allocations[i])}</span>`}</div>`).join('')}${draft?`<p class="form-footnote" id="draft-share">Your proposed share: ${money(allocations[0])}. Your current share stays ${money(currentPersonalAllocation(c))} until you send this proposal.</p>`:''}${method==='custom'?`<p class="form-footnote" id="custom-total">Shares must add up to ${money(c.total)}. A changed proposal needs everyone’s approval again.</p>`:''}</section>${method==='item'?`<section class="card-section"><button class="receipt-title" data-action="receipt" data-id="${id}" aria-expanded="${!!state.receiptOpen[id]}"><span>${icon('file-text')} &nbsp; Receipt review</span>${icon(state.receiptOpen[id]?'chevron-down':'chevron-right')}</button><p class="info-text" style="margin-top:9px">${isJuniper?'6 items · All items assigned':'No itemized receipt yet. Current shares are equal; use Custom to propose a different allocation.'}</p>${state.receiptOpen[id]?isJuniper?[['Burrata',16,'Jordan'],['Margherita pizza',24,'You'],['Rigatoni',28,'Maya'],['Branzino',36,'Jordan, Sam'],['Tiramisu',10,'Maya, Sam'],['Sparkling water',6,'You']].map(([n,a,o])=>`<div class="receipt-item"><span>${n}<small>${o}</small></span><strong>${money(a)}</strong></div>`).join(''):`<div class="receipt-item"><span>${esc(c.merchant)}<small>Split equally between ${members.length} people</small></span><strong>${money(c.total)}</strong></div>`:''}</section>`:''}${isJuniper?`<section class="card-section"><div class="detail-row row"><span class="row-label">Items subtotal</span><span class="row-value">$120.00</span></div><div class="detail-row row"><span class="row-label">Tax</span><span class="row-value">$10.20</span></div><div class="detail-row row"><span class="row-label">Tip</span><span class="row-value">$24.00</span></div><div class="detail-row row"><strong style="font-size:12px">Total</strong><span class="row-value">$154.20</span></div><p class="form-footnote">${method==='item'?'Tax and tip follow each person’s item total.':'Tax and tip are included in the amounts above.'}</p></section>`:''}`;}
function splitFooter(id){const c=pending.find(x=>x.id===id);const {draft}=splitView(c);return `<div class="footer-action">${button(state.approved[id]?icon('check')+' Share approved':draft?'Propose this split':'Approve my share · '+money(currentPersonalAllocation(c)),'approve',`data-id="${id}" ${state.approved[id]?'disabled':''}`)}<p>${state.approved[id]?'Your spending updates after the whole split settles.':draft?'A draft does not replace the current split until you send it.':'You approve only the amount shown. Changes require approval again.'}</p></div>`;}
function invitations(){return `${backbar('Invitations')}<h1 class="page-title">You’re invited.</h1><p class="page-sub">A new shared plan starts here.</p>${invites.map(i=>state.invites[i.id]?`<section class="invitation"><div class="row">${stamp(i)}<span class="pill ${state.invites[i.id]==='accepted'?'success':'muted'}">${state.invites[i.id]==='accepted'?'Accepted':'Declined'}</span></div><h2>${i.name}</h2><p class="info-text">${state.invites[i.id]==='accepted'?'Waiting for all invitations to be resolved before the group activates. Your approved contribution cap is '+money(i.share)+'.':'You declined this invitation. No contribution will be collected.'}</p></section>`:`<section class="invitation"><div class="row">${stamp(i)}<span class="pill">Invitation</span></div><h2>${i.name}</h2><p class="info-text">${i.from} invited you · ${i.members} people</p><div class="subtle-divider"></div><div class="detail-row row"><span class="row-label">Group budget</span><span class="row-value">${money(i.budget)}</span></div><div class="detail-row row"><span class="row-label">Your contribution cap</span><span class="row-value">${money(i.share)}</span></div><p class="form-footnote">By accepting, you authorize up to ${money(i.share)} to be collected automatically when all invitations are accepted or declined and at least two members have joined. Review the final amount before authorizing any increase.</p><div class="actions-pair">${button('Decline','invite',`data-id="${i.id}" data-response="declined"`,'secondary')}${button('Accept · '+money(i.share)+' cap','invite',`data-id="${i.id}" data-response="accepted"`)}</div></section>`).join('')}<p class="form-footnote">Preview only. No contribution or transfer occurs.</p>`;}
function notifications(){return `${backbar('Notifications')}<h1 class="page-title">You’re in the loop.</h1><p class="page-sub">A few things from your people.</p><div class="list-menu">${pending.map(c=>`<button class="menu-row" data-action="split" data-id="${c.id}">${stamp(gById(c.group))}<span class="menu-copy">${esc(c.name)}<small>${state.approved[c.id]?'Your share is approved. Waiting for the group.':'Your '+money(currentPersonalAllocation(c))+' share is ready to review.'}</small></span>${icon('chevron-right')}</button>`).join('')}<button class="menu-row" data-action="invitations">${icon('mail')}<span class="menu-copy">New group invitations<small>${invites.filter(i=>!state.invites[i.id]).length} invitations to review</small></span>${icon('chevron-right')}</button></div>`;}
function profile(){return `${backbar('Your profile')}<div class="profile-identity">${avatar(people[0],true)}<h1>${esc(state.displayName)} Zacharias</h1><small>@connorz · Sample profile</small></div><div class="list-menu">${[['edit-profile','users','Personal details','Name and profile'],['notifications-settings','bell','Notifications','Keep up with your groups'],['privacy','shield','Privacy','Your information stays with your group'],['about','help-circle','About this preview','How this prototype works']].map(([a,i,t,s])=>`<button class="menu-row" data-action="${a}">${icon(i)}<span class="menu-copy">${t}<small>${s}</small></span>${icon('chevron-right')}</button>`).join('')}</div>`;}
function groupMenu(type,id){const g=gById(id);const memberCount=g.members;const title={funds:'Funds',card:'Your card',members:'Members',budget:'Budget',settings:'Group settings'}[type];let body='';if(type==='funds')body=`<section class="card-section"><div class="eyebrow">Your balance in ${esc(g.name)}</div><div class="spending-total">${money(g.balance)}</div><p class="spending-caption">${money(g.available)} available in the group</p><div class="actions-pair">${button(icon('plus')+' Add funds','fund-form',`data-id="${id}" data-kind="add"`)}${button(icon('arrow-up-right')+' Withdraw','fund-form',`data-id="${id}" data-kind="withdraw"`,'secondary')}</div></section><div class="callout neutral">${icon('info')}<span>${pending.some(c=>c.group===id)?'Withdrawals are unavailable while this group has an unsettled split.':'Only your own available balance can be withdrawn.'} Funding reviews in this preview never move money.</span></div><section class="card-section"><div class="row"><div><strong style="font-size:12px">Auto-refill</strong><p class="info-text">Top up to your share each period.</p></div><button class="toggle ${state.autofill[id]!==false?'on':''}" role="switch" aria-checked="${state.autofill[id]!==false}" aria-label="Auto-refill" data-action="toggle" data-id="${id}" data-key="autofill"></button></div></section>`;if(type==='card')body=`<button class="card-launch" data-action="wallet" data-id="${id}" aria-label="Open mock Apple Pay">${cardVisual(g)}</button><p class="card-caption">Sample virtual card · No wallet or payment integration</p><section class="card-section" style="margin-top:24px"><div class="row"><div><strong style="font-size:12px">Freeze card</strong><p class="info-text">Temporarily pause this card.</p></div><button class="toggle ${state.frozen[id]?'on':''}" role="switch" aria-checked="${!!state.frozen[id]}" aria-label="Freeze card" data-action="toggle" data-id="${id}" data-key="frozen"></button></div></section><div class="list-menu"><button class="menu-row" data-action="card-details" data-id="${id}">${icon('credit-card')}<span>Card details</span>${icon('chevron-right')}</button></div>`;if(type==='members')body=`<h1 class="page-title">Your people.</h1><p class="page-sub">${memberCount} members · ${esc(g.name)}</p><section class="card-section">${(g.people||people.slice(0,memberCount)).map((p,i)=>`<div class="person-row">${avatar(p)}<div class="person-info"><strong>${i===0?esc(state.displayName)+' (you)':esc(p.name)}</strong><small>${i===0?'Group creator':'Member'}</small></div><span class="pill success">${g.forming?'Invited':'Up to date'}</span></div>`).join('')}</section>`;if(type==='budget')body=`<section class="card-section"><div class="eyebrow">Current group budget</div><div class="spending-total">${money(g.budget)}</div><p class="spending-caption">${g.period} · ${money(g.budget/memberCount)} per person</p></section><form data-form="budget" data-id="${id}"><label class="field"><span>Propose a new budget</span><input name="budget" type="number" min="1" max="100000" step=".01" required value="${g.budget}"><small>Everyone must agree. Increases and decreases take effect next period.</small></label><p class="form-error" role="alert"></p><button class="button full" type="submit">Review proposal ${icon('arrow-right')}</button></form>${g.proposedBudget?'<div class="callout">'+icon('info')+'<span>Your '+money(g.proposedBudget)+' budget proposal is waiting for the other members. The current budget is unchanged.</span></div>':''}`;if(type==='settings')body=`<div class="settings-group">${stamp(g)}<div><strong>${esc(g.name)}</strong><small>${g.members} members</small></div></div><div class="list-menu settings-menu">${[['group-edit','settings','Group name & photo','Make it yours'],['members','users','Members',g.members+' people'],['budget','calendar','Budget',money(g.budget)+' · '+g.period.toLowerCase()]].map(([route,i,label,detail])=>`<button class="menu-row" data-action="group-menu" data-id="${id}" data-menu="${route}">${icon(i)}<span class="menu-copy">${label}<small>${detail}</small></span>${icon('chevron-right')}</button>`).join('')}</div><section class="card-section"><label class="field" style="margin:0"><span>Default split</span><select id="default-split" data-id="${id}"><option ${g.defaultSplit!=='item'?'selected':''} value="equal">Equally</option><option ${g.defaultSplit==='item'?'selected':''} value="item">By item</option></select><small>Used for new purchases. Without a receipt, current shares start equal. Existing splits stay unchanged.</small></label></section>`;return backbar(title)+body;}
function createGroup(){return `${backbar('New group')}<h1 class="page-title">Make room for together.</h1><p class="page-sub">Start with your people and a shared budget.</p><form data-form="create"><label class="field"><span>Group name</span><input name="name" placeholder="e.g. The apartment" maxlength="32" required></label><div class="fields-row"><label class="field"><span>Group budget ($)</span><input name="budget" type="number" min="1" max="100000" step=".01" placeholder="300" required></label><label class="field"><span>Period</span><select name="period"><option>Every month</option><option>Every 2 weeks</option><option>Every week</option></select></label></div><label class="field"><span>Invite your people</span><input name="members" placeholder="maya, jordan" required><small>Enter 1–7 names separated by commas.</small></label><div class="callout">${icon('info')}<span>Everyone reviews their contribution cap first. Contributions collect automatically only after all invitations are resolved and at least two people join. Any increase above an approved cap needs fresh approval.</span></div><p class="form-error" role="alert"></p><button class="button full" type="submit">Review group ${icon('arrow-right')}</button><p class="form-footnote">This preview creates a local sample group. It sends no messages and collects no money.</p></form>`;}
function render(enter=false){const r=current();let html='',footer='';switch(r.type){case'home':html=home();break;case'all-pending':html=allPending();break;case'groups':html=groupsPage();break;case'spending':html=spending();break;case'group':html=groupDetail(r.id);break;case'wallet':html=wallet(r.id);break;case'group-edit':html=groupEdit(r.id);break;case'split':html=split(r.id);footer=splitFooter(r.id);break;case'invitations':html=invitations();break;case'notifications':html=notifications();break;case'profile':html=profile();break;case'create':html=createGroup();break;case'statistics':html=spending(r.id);break;default:html=groupMenu(r.type,r.id);}$('#app').innerHTML=`<section class="screen ${enter?'enter':''} ${r.type==='split'?'split-screen':''} ${r.type==='wallet'?'wallet-screen':''}" tabindex="-1">${html}</section>${footer}${!state.stack.length?navBar():''}`;$('.screen').scrollTop=state.scroll[routeKey()]||0;bindSplitPin();if(enter){const h=$('h1')||$('.backbar strong');if(h){h.tabIndex=-1;h.classList.add('focus-heading');h.focus({preventScroll:true});}}}
let lastFocus;
function modal(title,body){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button></div>${body}</section></div>`;$('#app').inert=true;requestAnimationFrame(()=>$('.modal input, .modal button, .modal select')?.focus());}
function closeModal(){ $('#modal-root').innerHTML='';$('#app').inert=false;state.modal=null;if(lastFocus?.isConnected)lastFocus.focus(); }
function simpleModal(title,body){modal(title,`<p class="info-text">${body}</p>${button('Got it','close-modal','','full')}`);}
function showFundForm(id,kind){const g=gById(id);if(kind==='withdraw'&&pending.some(c=>c.group===id)){simpleModal('A split is still pending','You can withdraw after every open split in '+esc(g.name)+' has settled. Approving your own share alone does not settle a split.');return;}modal(kind==='add'?'Add funds':'Withdraw funds',`<form data-form="funds" data-id="${id}" data-kind="${kind}"><label class="field"><span>Amount ($)</span><input name="amount" type="number" min="0.01" step=".01" ${kind==='withdraw'?`max="${g.balance}"`:''} placeholder="0.00" required><small>${kind==='withdraw'?'Your available balance: '+money(g.balance):'Add to your balance in '+esc(g.name)}</small></label><p class="form-error" role="alert"></p><button class="button full" type="submit">Review ${kind==='add'?'contribution':'withdrawal'}</button><p class="form-footnote">Preview only. No payment method is connected.</p></form>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(Date.now()<suppressCardClickUntil&&b.closest('[data-carousel]')){e.preventDefault();return;}const {action,id,menu,tab,dir,method,response,key,kind}=b.dataset;switch(action){case'carousel':setCarousel(id,Number(b.dataset.panel));break;case'wallet':if(Date.now()<suppressCardClickUntil)break;state.paymentResult=null;push('wallet',id);break;case'wallet-review':push('split',state.paymentResult);break;case'wallet-done':back();break;case'tab':nav(tab);break;case'back':back();break;case'profile':push('profile');break;case'notifications':state.notice=false;push('notifications');break;case'invitations':push('invitations');break;case'all-pending':push('all-pending');break;case'create':push('create');break;case'group':push('group',id);break;case'group-menu':if(menu==='group-edit'){photoReadVersion++;state.photoDraft={id,photo:groupPhoto(gById(id))};}push(menu,id);break;case'split':push('split',id);break;case'close-modal':closeModal();break;case'month':saveScroll();state.month=Math.max(0,Math.min(11,state.month+Number(dir)));render();break;case'legend':saveScroll();if(current().type!=='statistics')state.filter=state.filter===id?'all':id;render();break;case'receipt':saveScroll();state.receiptOpen[id]=!state.receiptOpen[id];render();break;case'split-method':saveScroll();if(method==='custom')state.editingCustom[id]=true;state.methods[id]=method;render();break;case'approve':{const c=pending.find(x=>x.id===id);const view=splitView(c);if(view.draft){const vals=view.method==='custom'?[...document.querySelectorAll('.custom-input')].map(i=>Math.round(Number(i.value)*100)):view.allocations.map(n=>Math.round(n*100));if(vals.length!==chargePeople(c).length||vals.some(n=>!Number.isFinite(n)||n<0)||vals.reduce((a,n)=>a+n,0)!==Math.round(c.total*100)){toast('The shares must add up exactly to '+money(c.total)+'.');return;}state.proposals[id]=vals.map(n=>n/100);state.publishedMethods[id]=view.method;state.editingCustom[id]=false;delete state.draftAmounts[id];state.approved[id]=false;saveScroll();render();toast('New proposal saved. Everyone needs to approve this version.');}else{state.approved[id]=true;saveScroll();render();toast('You’ve approved your share. Waiting for the rest of the group.');}break;}case'invite':state.invites[id]=response;if(response==='accepted'&&!groups.some(g=>g.id===id)){const invite=invites.find(i=>i.id===id);groups.push({...invite,members:invite.members,balance:0,power:0,available:0,total:0,forming:true,contributionCap:invite.share});}saveScroll();render();toast(response==='accepted'?'Invitation accepted in this preview. No contribution collected.':'Invitation declined. No contribution collected.');break;case'toggle':state[key][id]=!(state[key][id]??(key!=='frozen'));saveScroll();render();toast(key==='frozen'?(state.frozen[id]?'Card frozen in this preview.':'Card unfrozen in this preview.'):'Preference updated for this preview.');break;case'fund-form':showFundForm(id,kind);break;case'confirm-funds':closeModal();toast('Review complete. This preview did not transfer any money.');break;case'confirm-create':{const d=state.groupDraft;groups.push({id:'new-'+Date.now(),name:d.name,icon:'users',tone:'green',members:d.count,balance:0,power:0,available:0,total:0,budget:d.budget,period:d.period,forming:true,people:[people[0],...d.invitees.map((name,index)=>({name,initials:name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase(),tone:['maya','jordan','sam'][index%3]}))]});closeModal();state.stack=[];state.tab='groups';render();toast('Sample group created. Invitations and contributions are simulated.');break;}case'confirm-budget':gById(id).proposedBudget=state.budgetDraft;closeModal();render();toast('Proposal saved locally. Your current budget is unchanged.');break;case'edit-profile':modal('Personal details',`<form data-form="profile"><label class="field"><span>First name</span><input name="name" maxlength="24" required value="${esc(state.displayName)}"></label><button class="button full" type="submit">Save changes</button><p class="form-footnote">Only the name shown in this preview will change.</p></form>`);break;case'notifications-settings':modal('Notifications',`<p class="info-text">Choose what you would like to hear about.</p><div class="detail-row row"><span class="row-label">Split updates</span><button class="toggle ${state.notifySplits!==false?'on':''}" role="switch" aria-checked="${state.notifySplits!==false}" aria-label="Split updates" data-action="local-notify" data-key="notifySplits"></button></div><div class="detail-row row"><span class="row-label">Group invitations</span><button class="toggle ${state.notifyInvites!==false?'on':''}" role="switch" aria-checked="${state.notifyInvites!==false}" aria-label="Group invitations" data-action="local-notify" data-key="notifyInvites"></button></div><p class="form-footnote">No push notifications are sent from this preview.</p>${button('Done','close-modal','','full')}`);break;case'local-notify':state[key]=!(state[key]??true);b.classList.toggle('on',state[key]);b.setAttribute('aria-checked',String(state[key]));break;case'privacy':simpleModal('Private by design','In the product, your groups are visible only to their members. This standalone preview uses sample data, makes no account requests, and stores no personal details.');break;case'about':simpleModal('A space to explore','This is an interactive design prototype for chipin. All people, balances, cards, and purchases are sample data. Changes stay in this browser page and reset on reload. No real money moves.');break;case'card-details':simpleModal('Your sample card','Card ending 4826 · Connor Zacharias · '+esc(gById(id).name)+'. This visual card has no real card number, security code, wallet connection, or payment capability.');break;case'charge':{const c=charges.find(x=>x.id===id);modal(c.name,`<div class="row"><span class="row-label">${gById(c.group).name} · ${c.date}</span><span class="pill success">Settled</span></div><div class="spending-total" style="margin:22px 0">${money(c.amount)}</div><div class="detail-row row"><span class="row-label">Your share</span><span class="row-value">${money(c.amount)}</span></div><div class="detail-row row"><span class="row-label">Split method</span><span class="row-value">Equally</span></div><p class="form-footnote">All members approved. Sample transaction for this design preview.</p>${button('Done','close-modal','','full')}`);break;}}});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);const err=$('.form-error',form);const fail=t=>{if(err)err.textContent=t;};switch(form.dataset.form){case'payment':{const result=simulatePayment(form.dataset.id,String(f.get('merchant')),Number(f.get('amount')));if(result.error)return fail(result.error);saveScroll();state.scroll[routeKey()]=0;render(true);break;}case'group-edit':{const name=String(f.get('name')).trim();if(!name)return fail('Enter a group name.');const g=gById(form.dataset.id);g.name=name.slice(0,32);if(state.photoDraft?.id===g.id&&state.photoDraft.photo)g.photo=state.photoDraft.photo;state.photoDraft=null;back();toast('Group details updated in this preview.');break;}case'create':{const name=String(f.get('name')).trim(),budget=Number(f.get('budget')),members=String(f.get('members')).split(',').map(s=>s.trim()).filter(Boolean);if(!name||!members.length)return fail('Add a group name and at least one person.');if(members.length>7)return fail('This preview supports up to seven invitees.');if(!Number.isFinite(budget)||budget<=0)return fail('Enter a positive group budget.');state.groupDraft={name,budget,count:members.length+1,invitees:members,period:String(f.get('period'))};modal('Review your group',`<div class="detail-row row"><span class="row-label">Group</span><span class="row-value">${esc(name)}</span></div><div class="detail-row row"><span class="row-label">Budget</span><span class="row-value">${money(budget)}</span></div><div class="detail-row row"><span class="row-label">Your contribution cap</span><span class="row-value">${money(Math.ceil(budget*100/(members.length+1))/100)}</span></div><p class="form-footnote">${members.length+1} people · ${esc(f.get('period'))}. By continuing, you authorize this cap at activation, after all invitations are resolved with at least two members. No real contribution or invitation occurs in this preview.</p>${button('Create sample group','confirm-create','','full')}${button('Keep editing','close-modal','','secondary full')}`);break;}case'funds':{const amount=Number(f.get('amount'));const g=gById(form.dataset.id);if(!Number.isFinite(amount)||amount<=0||Math.abs(amount*100-Math.round(amount*100))>.00001)return fail('Enter a positive amount with at most two decimal places.');if(form.dataset.kind==='withdraw'&&amount>g.balance)return fail('The amount exceeds your available balance.');modal('Review '+(form.dataset.kind==='add'?'contribution':'withdrawal'),`<div class="eyebrow">${esc(g.name)}</div><div class="spending-total" style="margin:12px 0 20px">${money(amount)}</div><p class="info-text">This is a form preview. Confirming completes the review step without charging a card, transferring funds, or changing your balance.</p>${button('Finish review','confirm-funds','','full')}${button('Cancel','close-modal','','secondary full')}`);break;}case'budget':{const budget=Number(f.get('budget'));if(!Number.isFinite(budget)||budget<=0)return fail('Enter a positive budget.');if(budget===gById(form.dataset.id).budget)return fail('Enter a different budget to propose a change.');state.budgetDraft=budget;modal('Review budget proposal',`<div class="spending-total">${money(budget)}</div><p class="info-text" style="margin-top:15px">${money(budget/gById(form.dataset.id).members)} per member. Everyone must approve this proposal. It takes effect next period; current balances and this period’s budget stay unchanged.</p><p class="form-footnote">This saves a proposal only in the preview.</p>${button('Propose to group','confirm-budget',`data-id="${form.dataset.id}"`,'full')}${button('Keep editing','close-modal','','secondary full')}`);break;}case'profile':state.displayName=String(f.get('name')).trim()||'Connor';closeModal();render();toast('Your preview profile has been updated.');break;}});
document.addEventListener('change',e=>{if(e.target.id==='charge-filter'){saveScroll();state.filter=e.target.value;render();}if(e.target.matches('[name="group-photo"]')){photoReadVersion++;state.photoDraft={id:current().id,photo:groupPhotos[e.target.value]};const preview=$('#group-photo-preview');if(preview)preview.src=state.photoDraft.photo;}if(e.target.id==='photo-upload'){readGroupPhoto(e.target);}if(e.target.id==='default-split'){gById(e.target.dataset.id).defaultSplit=e.target.value;toast('Default split updated for future sample purchases.');}});
document.addEventListener('input',e=>{if(e.target.matches('.custom-input')){const inputs=[...document.querySelectorAll('.custom-input')];const total=inputs.reduce((a,i)=>a+Math.round(Number(i.value||0)*100),0)/100;const c=pending.find(x=>x.id===current().id);$('#custom-total').textContent=money(total)+' of '+money(c.total)+' allocated. New proposals need everyone’s approval again.';state.draftAmounts[c.id]=inputs.map(i=>Number(i.value)||0);const stickyDraft=$('#sticky-draft-amount');if(stickyDraft)stickyDraft.textContent='Draft '+money(state.draftAmounts[c.id][0])+' · not sent';const draftShare=$('#draft-share');if(draftShare)draftShare.textContent='Your proposed share: '+money(state.draftAmounts[c.id][0])+'. Your current share stays '+money(currentPersonalAllocation(c))+' until you send this proposal.';}});
document.addEventListener('keydown',e=>{const m=$('.modal');if(!m)return;if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const f=[...m.querySelectorAll('button:not(:disabled),input,select,a[href]')];if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus();}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();if(e.target.closest('.brand')){e.preventDefault();nav('home');}});
window.addEventListener('hashchange',()=>{if(location.hash==='#home')nav('home');});

function groupEdit(id){const g=gById(id),photo=state.photoDraft?.id===id?state.photoDraft.photo:groupPhoto(g);return `${backbar('Group name & photo')}<h1 class="page-title">Make it yours.</h1><p class="page-sub">A familiar face for your shared plans.</p><form data-form="group-edit" data-id="${id}"><div class="photo-edit-preview"><img id="group-photo-preview" src="${esc(photo||groupPhotos.apartment)}" alt="Selected group photo"></div><label class="field"><span>Group name</span><input name="name" value="${esc(g.name)}" maxlength="32" required></label><fieldset class="photo-options"><legend>Group photo</legend>${Object.entries(groupPhotos).map(([key,src])=>`<label><input type="radio" name="group-photo" value="${key}" ${photo===src?'checked':''}><img src="${src}" alt="${key==='weekend'?'Dinner table':key==='roadtrip'?'Forest':'Apartment'}"></label>`).join('')}</fieldset><label class="upload-photo">${icon('plus')} Choose your own photo<input type="file" id="photo-upload" accept="image/jpeg,image/png,image/webp,image/gif"><small>JPG, PNG, WebP or GIF · up to 5 MB · stays on this page</small></label><p class="form-error" role="alert"></p><button class="button full" type="submit">Save changes</button></form>`;}
function readGroupPhoto(input){const file=input.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)||file.size>5*1024*1024){$('.form-error').textContent='Choose a JPG, PNG, WebP or GIF up to 5 MB.';input.value='';return;}const id=current().id,version=++photoReadVersion,reader=new FileReader();reader.onload=()=>{if(version!==photoReadVersion||current().type!=='group-edit'||current().id!==id)return;state.photoDraft={id,photo:String(reader.result)};$('#group-photo-preview').src=state.photoDraft.photo;document.querySelectorAll('[name="group-photo"]').forEach(r=>r.checked=false);$('.form-error').textContent='';};reader.onerror=()=>{$('.form-error').textContent='This photo could not be read. Try another image.';};reader.readAsDataURL(file);}
function wallet(id){const g=gById(id),c=pending.find(c=>c.id===state.paymentResult);if(c)return `${backbar('Apple Pay · Preview')}<div class="payment-success"><div class="success-circle">${icon('check')}</div><h1>Payment simulated</h1><div class="payment-amount">${money(c.total)}</div><p>at ${esc(c.merchant)}</p><div class="wallet-card-arrival">${cardVisual(g)}</div><p class="info-text">A pending split was added to ${esc(g.name)}.<br>Your current share is ${money(currentPersonalAllocation(c))}.</p>${button('Review split','wallet-review','','full')}${button('Back to group','wallet-done','','secondary full')}<p class="form-footnote">No money moved. No wallet or payment provider was contacted.</p></div>`;return `${backbar('')}<div class="wallet-heading"><h1>Apple Pay</h1><span class="pill">Preview</span></div><p class="page-sub">Simulate a purchase with your group card.</p><div class="wallet-card-arrival">${cardVisual(g)}</div><div class="wallet-group">${stamp(g)}<span>${esc(g.name)}<small>${money(g.available)} available after holds</small></span></div><form data-form="payment" data-id="${id}"><label class="field"><span>Merchant</span><input name="merchant" value="Blue Bottle" maxlength="48" required></label><label class="field"><span>Purchase amount ($)</span><input name="amount" type="number" min="0.01" step=".01" value="24.00" required></label><p class="form-error" role="alert"></p><button class="button full payment-button" type="submit" ${state.frozen[id]||g.forming?'disabled':''}>${icon('credit-card')} Simulate payment</button><p class="form-footnote">${state.frozen[id]?'Unfreeze this card in Card controls to simulate a purchase.':g.forming?'This group must activate before it can make purchases.':'No wallet or payment provider is connected. This only adds a local pending split.'}</p></form>`;}
function simulatePayment(id,merchant,amount){const g=gById(id);if(state.paymentResult)return {error:'This payment was already simulated.'};if(g.forming||state.frozen[id])return {error:'This group card is not available for purchases.'};if(!merchant.trim())return {error:'Enter a merchant name.'};if(!Number.isFinite(amount)||amount<=0||Math.abs(amount*100-Math.round(amount*100))>.00001)return {error:'Enter a positive amount with at most two decimal places.'};if(Math.round(amount*100)>Math.round(g.available*100))return {error:'This amount exceeds the group’s available funds.'};const members=(g.people||people.slice(0,g.members)).map(p=>({...p}));const c={id:'simulated-'+(++state.paymentSequence),name:merchant.trim().slice(0,48),merchant:merchant.trim().slice(0,48),group:id,total:Math.round(amount*100)/100,members:members.length,people:members,allocation:equalAllocation(amount,members.length),initialMethod:g.defaultSplit||'equal',initialApprovals:0,month:9,date:'Oct 17 · Just now',icon:'shopping-bag',simulated:true};pending.unshift(c);g.available=(Math.round(g.power*100)-pending.filter(p=>p.group===id).reduce((sum,p)=>sum+Math.round(p.total*100),0))/100;state.paymentResult=c.id;state.notice=true;return c;}
function bindSplitPin(){if(current().type!=='split')return;const screen=$('.screen'),summary=$('.split-summary');if(!summary)return;const update=()=>summary.style.setProperty('--compact',String(Math.max(0,Math.min(1,(screen.scrollTop-24)/72))));screen.addEventListener('scroll',update,{passive:true});update();}
let swipeStart=null,suppressCardClickUntil=0,photoReadVersion=0;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-carousel]');if(el)swipeStart={id:el.dataset.carousel,x:e.clientX,y:e.clientY};});
document.addEventListener('pointerup',e=>{if(!swipeStart)return;const start=swipeStart;swipeStart=null;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.3){suppressCardClickUntil=Date.now()+500;e.preventDefault();setCarousel(start.id,(state.carousel[start.id]||0)===0?1:0);}});
document.addEventListener('pointercancel',()=>{swipeStart=null;});
document.addEventListener('keydown',e=>{const carousel=e.target.closest('[data-carousel]');if(carousel&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){e.preventDefault();setCarousel(carousel.dataset.carousel,(state.carousel[carousel.dataset.carousel]||0)===0?1:0);}});
render();
